# Check System Manager role using DB (safe_exec compatible)
is_system_manager = frappe.db.exists(
    "Has Role",
    {
        "parent": user,
        "role": "System Manager"
    }
)

if is_system_manager:
    conditions = "1=1"
else:
    diwan = frappe.db.get_value(
        "User Diwan Mapping",
        {"user": user},
        "diwan"
    )

    if not diwan:
        conditions = "1=0"
    else:
        conditions = f"""
        (
            (
                `tabMail Register`.`mail_type` = 'Outgoing'
                AND `tabMail Register`.`issuing_office` = '{diwan}'
            )
            OR
            (
                `tabMail Register`.`mail_type` = 'Incoming'
                AND `tabMail Register`.`receiver_office` = '{diwan}'
            )
        )
        """

doc = frappe.get_doc("Mail Register", doc.name)

if doc.mail_type == "Outgoing":

    for r in doc.recipients:
        if r.status != "Sent":
            continue

        exists = frappe.db.exists(
            "Incoming Confirmation Queue",
            {
                "mail_recipient_row": r.name
            }
        )

        if exists:
            continue

        queue = frappe.new_doc("Incoming Confirmation Queue")
        queue.mail_register = doc.name
        queue.mail_recipient_row = r.name
        queue.recipient_office = r.recipient_office
        queue.status = r.status

        queue.mail_number = doc.mail_number
        queue.mail_date = doc.mail_date
        queue.subject = doc.subject

        queue.received_confirmed = 0

        queue.insert(ignore_permissions=True)

user = frappe.session.user

# System Manager يرى كل شيء
is_system_manager = frappe.db.exists(
    "Has Role",
    {
        "parent": user,
        "role": "System Manager"
    }
)

if is_system_manager:
    conditions = "1=1"
else:
    # جلب ديوان المستخدم
    diwan = frappe.db.get_value(
        "User Diwan Mapping",
        {"user": user},
        "diwan"
    )

    if not diwan:
        conditions = "1=0"
    else:
        conditions = (
            "`tabIncoming Confirmation Queue`.`recipient_office` = "
            f"'{diwan}'"
        )

# ===============================
# Set Root Outgoing Mail
# ===============================

# إذا كان الجذر مملوء مسبقًا لا نغيره
if doc.root_outgoing_mail:
    pass

# 📤 صادر جديد (ليس رد)
elif doc.mail_type == "Outgoing" and not doc.reply_to:
    doc.root_outgoing_mail = doc.name

# 📤 صادر رد (يرث الجذر من الأصل)
elif doc.mail_type == "Outgoing" and doc.reply_to:
    parent = frappe.get_doc("Mail Register", doc.reply_to)

    if parent.root_outgoing_mail:
        doc.root_outgoing_mail = parent.root_outgoing_mail
    else:
        doc.root_outgoing_mail = parent.name

# 📥 وارد مُنشأ من صادر
elif doc.mail_type == "Incoming" and doc.linked_outgoing_mail:
    outgoing = frappe.get_doc("Mail Register", doc.linked_outgoing_mail)

    # إن كان الصادر الأصلي
    if outgoing.root_outgoing_mail:
        doc.root_outgoing_mail = outgoing.root_outgoing_mail
    else:
        doc.root_outgoing_mail = outgoing.name

# لا نغيّر الحالة إذا كانت Received
if doc.status == "Received":
    pass
else:
    has_internal = len(doc.recipients or []) > 0
    has_external = len(doc.external_recipients or []) > 0

    if (has_internal or has_external):
        doc.status = "Sent"
    else:
        doc.status = "Draft"
